import cmath
import math


def magnitude(z):
    return abs(z)


def rotate(z, angle_degrees):
    angle_rad = math.radians(angle_degrees)
    return z * cmath.exp(1j * angle_rad)


def roots_of_unity(n):
    return [cmath.exp(2j * cmath.pi * k / n) for k in range(n)]


def mandelbrot_escape(c, max_iter=100):
    z = 0
    for i in range(max_iter):
        z = z * z + c
        if abs(z) > 2:
            return i
    return max_iter
